CREATE TABLE IF NOT EXISTS notifications (id text PRIMARY KEY, owner_id text NOT NULL REFERENCES users(id), event_key text NOT NULL, title text NOT NULL, body text NOT NULL, href text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), read_at timestamptz, UNIQUE(owner_id,event_key));
CREATE INDEX IF NOT EXISTS notifications_owner_created ON notifications(owner_id,created_at DESC);
CREATE TABLE IF NOT EXISTS push_subscriptions (id text PRIMARY KEY, owner_id text NOT NULL REFERENCES users(id), endpoint text NOT NULL UNIQUE, keys jsonb NOT NULL, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS push_deliveries (id text PRIMARY KEY, notification_id text NOT NULL REFERENCES notifications(id) ON DELETE CASCADE, subscription_id text NOT NULL REFERENCES push_subscriptions(id) ON DELETE CASCADE, state text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), locked_at timestamptz, last_status integer, UNIQUE(notification_id,subscription_id));
